1	package vram
2	
3	import (
4		"context"
5		"log/slog"
6		"math"
7		"sync"
8		"time"
9	
10		"github.com/nogo/wire/internal/monitor"
11	)
12	
13	// Tracker manages VRAM budget tracking, admission control, and sysfs reconciliation.
14	type Tracker struct {
15		backend      Backend
16		hfCache      *HFCache
17		estimates    sync.Map // modelRef → uint64 (VRAM estimate bytes)
18		reservations sync.Map // modelRef → uint64 (reserved bytes)
19		pending      sync.Map // modelRef → uint64 (pending release, waiting for sysfs confirmation)
20	
21		gpuStateCh chan []monitor.GPUMetrics // published to Hub
22	
23		totalVRAM uint64
24		mu        sync.RWMutex
25	
26		ctx    context.Context
27		cancel context.CancelFunc
28		wg     sync.WaitGroup
29	}
30	
31	// New creates a Tracker with the given backend and HF cache scanner.
32	// Call Discover() then Start() to begin tracking.
33	func New(backend Backend, hfCache *HFCache) *Tracker {
34		ctx, cancel := context.WithCancel(context.Background())
35		return &Tracker{
36			backend:    backend,
37			hfCache:    hfCache,
38			gpuStateCh: make(chan []monitor.GPUMetrics, 64),
39			ctx:        ctx,
40			cancel:     cancel,
41		}
42	}
43	
44	// HFCache returns the HF cache scanner for manual scanning if needed.
45	func (t *Tracker) HFCache() *HFCache {
46		return t.hfCache
47	}
48	
49	// Discover runs the backend auto-detection chain and populates totalVRAM.
50	// Returns the discovered GPUs.
51	func (t *Tracker) Discover() []monitor.GPUInfo {
52		gpus := t.backend.Discover()
53		if t.backend.IsNoop() {
54			slog.Info("VRAM tracker: noop backend (CPU-only)")
55			return gpus
56		}
57		t.mu.Lock()
58		t.totalVRAM = t.backend.TotalVRAM()
59		t.mu.Unlock()
60		slog.Info("VRAM tracker: discovered GPUs", "count", len(gpus), "total_vram", t.totalVRAM)
61		return gpus
62	}
63	
64	// CanFit reports whether estimate bytes would fit in the current VRAM budget.
65	// Budget = total - (actual_sysfs_used + pending_releases).
66	func (t *Tracker) CanFit(estimate uint64) bool {
67		if t.backend.IsNoop() {
68			return true
69		}
70		t.mu.RLock()
71		total := t.totalVRAM
72		t.mu.RUnlock()
73	
74		actualUsed := t.backend.UsedVRAM()
75		pending := t.pendingTotal()
76	
77		sum := actualUsed + pending
78		if sum >= total {
79			return false
80		}
81		return estimate <= total-sum
82	}
83	
84	// FreeVRAM returns the current VRAM budget available for new models:
85	// total − actual_sysfs_used − pending_releases.
86	// Returns math.MaxUint64 for noop (CPU-only) backends.
87	func (t *Tracker) FreeVRAM() uint64 {
88		if t.backend.IsNoop() {
89			return math.MaxUint64
90		}
91		t.mu.RLock()
92		total := t.totalVRAM
93		t.mu.RUnlock()
94		used := t.backend.UsedVRAM()
95		pending := t.pendingTotal()
96		sum := used + pending
97		if sum >= total {
98			return 0
99		}
100		return total - sum
101	}
102	
103	// Reserve marks VRAM for a model. estimate is the expected VRAM consumption.
104	// Returns false if the model is already reserved or if it would exceed budget.
105	func (t *Tracker) Reserve(model string, estimate uint64) bool {
106		if t.backend.IsNoop() {
107			return true
108		}
109		if _, loaded := t.reservations.LoadOrStore(model, estimate); loaded {
110			return true // already reserved
111		}
112		if !t.CanFit(estimate) {
113			t.reservations.Delete(model)
114			return false
115		}
116		slog.Info("VRAM reserved", "model", model, "bytes", estimate)
117		return true
118	}
119	
120	// Release marks a model's VRAM as pending release.
121	// The reservation is moved to pending until sysfs reconciliation confirms the drop.
122	func (t *Tracker) Release(model string) {
123		if t.backend.IsNoop() {
124			return
125		}
126		if v, loaded := t.reservations.LoadAndDelete(model); loaded {
127			t.pending.Store(model, v)
128			slog.Info("VRAM release pending", "model", model, "bytes", v)
129		}
130	}
131	
132	// EstimateForModel returns the VRAM estimate for a model reference.
133	// It checks the HF cache scan first, then tries to stat the path directly.
134	func (t *Tracker) EstimateForModel(modelRef string) uint64 {
135		if t.hfCache != nil {
136			if v := t.hfCache.Estimate(modelRef); v > 0 {
137				return v
138			}
139		}
140		if v, ok := t.estimates.Load(modelRef); ok {
141			return v.(uint64)
142		}
143		// Try placeholder based on model name.
144		if v := PlaceholderVRAM(modelRef); v > 0 {
145			t.estimates.Store(modelRef, v)
146			return v
147		}
148		return 0
149	}
150	
151	// SetEstimate records a VRAM estimate for a model reference.
152	func (t *Tracker) SetEstimate(modelRef string, estimate uint64) {
153		t.estimates.Store(modelRef, estimate)
154	}
155	
156	// GPUStateCh returns a receive-only channel that delivers GPU metrics snapshots.
157	// Hub subscribes to this channel for MsgGPUTick messages.
158	func (t *Tracker) GPUStateCh() <-chan []monitor.GPUMetrics {
159		return t.gpuStateCh
160	}
161	
162	// Start begins the poll loop that reconciles reservations with sysfs readings.
163	func (t *Tracker) Start() {
164		t.wg.Add(1)
165		go t.pollLoop()
166	}
167	
168	// Stop cancels the poll loop and waits for it to exit.
169	func (t *Tracker) Stop() {
170		t.cancel()
171		t.wg.Wait()
172		close(t.gpuStateCh)
173	}
174	
175	// pendingTotal returns the sum of all pending-release VRAM.
176	func (t *Tracker) pendingTotal() uint64 {
177		var total uint64
178		t.pending.Range(func(_, v interface{}) bool {
179			total += v.(uint64)
180			return true
181		})
182		return total
183	}
184	
185	// reservedTotal returns the sum of all active reservations.
186	func (t *Tracker) reservedTotal() uint64 {
187		var total uint64
188		t.reservations.Range(func(_, v interface{}) bool {
189			total += v.(uint64)
190			return true
191		})
192		return total
193	}
194	
195	func (t *Tracker) pollLoop() {
196		defer t.wg.Done()
197		ticker := time.NewTicker(time.Second)
198		defer ticker.Stop()
199	
200		for {
201			select {
202			case <-t.ctx.Done():
203				return
204			case <-ticker.C:
205				t.reconcile()
206				t.pushGPUState()
207			}
208		}
209	}
210	
211	// reconcile compares sysfs actual VRAM used against tracked reservations+pending,
212	// and clears stale entries where actual usage has dropped.
213	func (t *Tracker) reconcile() {
214		if t.backend.IsNoop() {
215			return
216		}
217		actualUsed := t.backend.UsedVRAM()
218		reserved := t.reservedTotal()
219		pending := t.pendingTotal()
220	
221		// Clear pending releases where sysfs shows the VRAM has been freed.
222		if pending > 0 && actualUsed < reserved+pending {
223			t.pending.Range(func(key, val interface{}) bool {
224				// If actual usage dropped significantly, assume this model's VRAM was freed.
225				if actualUsed <= reserved {
226					t.pending.Delete(key)
227					slog.Info("VRAM release confirmed by sysfs", "model", key)
228				}
229				return true
230			})
231		}
232	
233		// If sysfs shows less used than we think is reserved, something was
234		// externally freed — clear all reservations to stay aligned.
235		if actualUsed < reserved {
236			t.reservations.Range(func(key, _ interface{}) bool {
237				slog.Warn("VRAM mismatch: sysfs lower than reserved, clearing reservation",
238					"model", key, "actual_used", actualUsed, "reserved", reserved)
239				t.reservations.Delete(key)
240				return true
241			})
242		}
243	}
244	
245	// pushGPUState reads GPU metrics and sends them to the Hub channel.
246	func (t *Tracker) pushGPUState() {
247		metrics := t.backend.ReadMetrics()
248		select {
249		case t.gpuStateCh <- metrics:
250		default:
251			// Drop if Hub consumer is slow.
252		}
253	}
