1	package config
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"log/slog"
8		"os"
9		"path/filepath"
10		"strings"
11		"time"
12	
13		"gopkg.in/yaml.v3"
14	)
15	
16	// Duration is a time.Duration that unmarshals from a YAML string like "30s".
17	type Duration time.Duration
18	
19	func (d *Duration) UnmarshalYAML(unmarshal func(interface{}) error) error {
20		var s string
21		if err := unmarshal(&s); err != nil {
22			return err
23		}
24		dur, err := time.ParseDuration(s)
25		if err != nil {
26			return err
27		}
28		*d = Duration(dur)
29		return nil
30	}
31	
32	// Path returns the resolved config file path.
33	// Resolution order: WIRE_CONFIG env var → XDG_CONFIG_HOME/wire/config.yaml →
34	// ~/.config/wire/config.yaml.
35	func Path() string {
36		if v := os.Getenv("WIRE_CONFIG"); v != "" {
37			return v
38		}
39		base := os.Getenv("XDG_CONFIG_HOME")
40		if base == "" {
41			home, _ := os.UserHomeDir()
42			base = filepath.Join(home, ".config")
43		}
44		return filepath.Join(base, "wire", "config.yaml")
45	}
46	
47	// Provider defines a remote OpenAI-compatible API provider.
48	type Provider struct {
49		BaseURL    string `yaml:"base_url"`
50		APIKey     string `yaml:"api_key"`
51		ListModels *bool  `yaml:"list_models"`
52	}
53	
54	// ShouldListModels reports whether Wire should fetch the provider's model list.
55	// Defaults to true when not explicitly set.
56	func (p Provider) ShouldListModels() bool {
57		return p.ListModels == nil || *p.ListModels
58	}
59	
60	type Config struct {
61		Listen       string                 `yaml:"listen"`
62		Monitor      bool                   `yaml:"monitor"`
63		MaxModels    int                    `yaml:"max_models"`
64		HFCacheDir   string                 `yaml:"hf_cache_dir"`
65		DrainTimeout Duration               `yaml:"drain_timeout"`
66		QueueDepth   int                    `yaml:"queue_depth"`
67		Providers    map[string]Provider    `yaml:"providers"`
68		Models       map[string]ModelParams `yaml:"models"`
69		Warmup       []string               `yaml:"warmup"`
70	}
71	
72	type ModelParams struct {
73		Context    int      `yaml:"context"`
74		GPULayers  int      `yaml:"gpu_layers"`
75		Slots      int      `yaml:"slots"`
76		Pooling    string   `yaml:"pooling"`
77		Extra      []string `yaml:"extra"`
78		SpecType   string   `yaml:"spec_type"`
79		DraftMax   int      `yaml:"draft_max"`
80		DraftMin   int      `yaml:"draft_min"`
81		SpecNgramN int      `yaml:"spec_ngram_n"`
82		SpecNgramM int      `yaml:"spec_ngram_m"`
83	
84		// Remote provider fields. When Provider is set, this model proxies to a
85		// remote API instead of a local llama-server process.
86		Provider      string   `yaml:"provider"`
87		UpstreamModel string   `yaml:"upstream_model"`
88		Capabilities  []string `yaml:"capabilities"`
89	}
90	
91	// IsRemote reports whether this model is backed by a remote provider.
92	func (p ModelParams) IsRemote() bool { return p.Provider != "" }
93	
94	// Equal reports whether p and other have identical parameters.
95	// []string (Extra) is compared element-by-element.
96	func (p ModelParams) Equal(other ModelParams) bool {
97		if p.Context != other.Context ||
98			p.GPULayers != other.GPULayers ||
99			p.Slots != other.Slots ||
100			p.Pooling != other.Pooling ||
101			p.SpecType != other.SpecType ||
102			p.DraftMax != other.DraftMax ||
103			p.DraftMin != other.DraftMin ||
104			p.SpecNgramN != other.SpecNgramN ||
105			p.SpecNgramM != other.SpecNgramM ||
106			p.Provider != other.Provider ||
107			p.UpstreamModel != other.UpstreamModel ||
108			len(p.Extra) != len(other.Extra) ||
109			len(p.Capabilities) != len(other.Capabilities) {
110			return false
111		}
112		for i, v := range p.Extra {
113			if v != other.Extra[i] {
114				return false
115			}
116		}
117		for i, v := range p.Capabilities {
118			if v != other.Capabilities[i] {
119				return false
120			}
121		}
122		return true
123	}
124	
125	// MatchModel returns the ModelParams for the first glob pattern in Models that
126	// matches name. Returns zero ModelParams and false if no pattern matches.
127	func (c *Config) MatchModel(name string) (ModelParams, bool) {
128		for pattern, params := range c.Models {
129			matched, err := filepath.Match(pattern, name)
130			if err == nil && matched {
131				return params, true
132			}
133		}
134		return ModelParams{}, false
135	}
136	
137	// Load reads the config from disk, applies defaults, and validates it.
138	func Load() (*Config, error) {
139		path := Path()
140	
141		data, err := os.ReadFile(path)
142		if err != nil {
143			if errors.Is(err, os.ErrNotExist) {
144				return nil, fmt.Errorf("config file not found at %s: %w", path, err)
145			}
146			return nil, fmt.Errorf("reading config %s: %w", path, err)
147		}
148	
149		cfg := new(Config)
150		dec := yaml.NewDecoder(bytes.NewReader(data))
151		dec.KnownFields(true)
152		if err := dec.Decode(cfg); err != nil {
153			return nil, fmt.Errorf("parsing config %s: %w", path, err)
154		}
155	
156		expandProviderEnvVars(cfg)
157		applyDefaults(cfg)
158	
159		if err := validate(cfg); err != nil {
160			return nil, err
161		}
162	
163		return cfg, nil
164	}
165	
166	// knownProviderBaseURLs maps well-known provider names to their default API base URLs.
167	var knownProviderBaseURLs = map[string]string{
168		"openai":     "https://api.openai.com",
169		"openrouter": "https://openrouter.ai/api",
170		"groq":       "https://api.groq.com/openai",
171		"together":   "https://api.together.xyz",
172		"mistral":    "https://api.mistral.ai",
173		"deepseek":   "https://api.deepseek.com",
174	}
175	
176	// expandProviderEnvVars replaces ${VAR} references in provider API keys with
177	// the corresponding environment variable value.
178	func expandProviderEnvVars(cfg *Config) {
179		for name, p := range cfg.Providers {
180			if strings.HasPrefix(p.APIKey, "${") && strings.HasSuffix(p.APIKey, "}") {
181				envVar := p.APIKey[2 : len(p.APIKey)-1]
182				p.APIKey = os.Getenv(envVar)
183				cfg.Providers[name] = p
184			}
185		}
186	}
187	
188	func applyDefaults(cfg *Config) {
189		if cfg.Listen == "" {
190			cfg.Listen = ":9480"
191		}
192		if cfg.MaxModels == 0 {
193			cfg.MaxModels = 1
194		}
195		if cfg.HFCacheDir == "" {
196			home, _ := os.UserHomeDir()
197			cfg.HFCacheDir = filepath.Join(home, ".cache", "huggingface", "hub")
198		}
199		if cfg.DrainTimeout == Duration(0) {
200			cfg.DrainTimeout = Duration(30 * time.Second)
201		} else {
202			_ = time.Duration(cfg.DrainTimeout) // ensure valid
203		}
204		if cfg.QueueDepth == 0 {
205			cfg.QueueDepth = 200
206		}
207		for pattern, p := range cfg.Models {
208			if p.Slots == 0 && !p.IsRemote() {
209				p.Slots = 1
210				cfg.Models[pattern] = p
211			}
212		}
213		for name, p := range cfg.Providers {
214			if p.BaseURL == "" {
215				if defaultURL, ok := knownProviderBaseURLs[name]; ok {
216					p.BaseURL = defaultURL
217					cfg.Providers[name] = p
218				}
219			}
220		}
221	}
222	
223	func validate(cfg *Config) error {
224		// Validate providers.
225		for name, p := range cfg.Providers {
226			if p.APIKey == "" {
227				return fmt.Errorf("provider %q: api_key is empty (set the environment variable or provide a literal value)", name)
228			}
229			if p.BaseURL == "" {
230				return fmt.Errorf("provider %q: base_url is required (no known default for this provider name)", name)
231			}
232		}
233	
234		// Validate warmup entries. Unmatched entries are dropped with a warning so
235		// the daemon still starts when a model has been removed from the config.
236		kept := cfg.Warmup[:0]
237		for _, entry := range cfg.Warmup {
238			var matches int
239			for pattern, p := range cfg.Models {
240				matched, err := filepath.Match(pattern, entry)
241				if err == nil && matched {
242					if p.IsRemote() {
243						return fmt.Errorf("warmup entry %q references a remote model (remote models cannot be warmed up)", entry)
244					}
245					matches++
246				}
247			}
248			if matches == 0 {
249				slog.Warn("warmup entry does not match any model pattern; skipping", "entry", entry)
250				continue
251			}
252			if matches > 1 {
253				return fmt.Errorf("warmup entry %q matches %d model patterns (expected 1)", entry, matches)
254			}
255			kept = append(kept, entry)
256		}
257		cfg.Warmup = kept
258		if len(cfg.Warmup) > cfg.MaxModels {
259			return fmt.Errorf("warmup list length %d exceeds max_models %d", len(cfg.Warmup), cfg.MaxModels)
260		}
261	
262		validSpecTypes := map[string]bool{
263			"ngram-simple":  true,
264			"ngram-mod":     true,
265			"ngram-cache":   true,
266			"ngram-map-k":   true,
267			"ngram-map-k4v": true,
268		}
269		for pattern, p := range cfg.Models {
270			if p.SpecType != "" && !validSpecTypes[p.SpecType] {
271				return fmt.Errorf("model pattern %q: invalid spec_type %q (valid: ngram-simple, ngram-mod, ngram-cache, ngram-map-k, ngram-map-k4v)", pattern, p.SpecType)
272			}
273	
274			// Remote model validation.
275			if p.IsRemote() {
276				if _, ok := cfg.Providers[p.Provider]; !ok {
277					return fmt.Errorf("model pattern %q: references unknown provider %q", pattern, p.Provider)
278				}
279				if p.Context != 0 || p.GPULayers != 0 || p.Slots != 0 || p.Pooling != "" || len(p.Extra) != 0 || p.SpecType != "" {
280					return fmt.Errorf("model pattern %q: remote models cannot set local-only fields (context, gpu_layers, slots, pooling, extra, spec_type)", pattern)
281				}
282			}
283		}
284		return nil
285	}
