	cfg, err := Load()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(cfg.Warmup) != 1 || cfg.Warmup[0] != "org/model-A" {
		t.Errorf("unmatched warmup entry should be dropped, got: %v", cfg.Warmup)
	}
}

func TestLoad_WarmupMultiplePatternMatch(t *testing.T) {
	path := writeConfig(t, `
models:
  "org/model-*":
