func TestLoad_XDGConfigHome(t *testing.T) {
	xdg := t.TempDir()
	confDir := filepath.Join(xdg, "wire")
	if err := os.MkdirAll(confDir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(confDir, "config.yaml"), []byte(`
