func TestLoad_ExplicitValues(t *testing.T) {
	_ = writeConfig(t, `
listen: ":9090"
monitor: true
max_models: 3
models:
  "org/model-A":
    context: 8192
    gpu_layers: 35
    slots: 4
    pooling: "mean"
  "org/model-B":
    context: 2048
warmup:
  - "org/model-A"
  - "org/model-B"
  - "org/model-C"
`)
	// max_models=3 and 3 warmup entries — valid, but model-C has no pattern match.
	// Use a valid config instead.
	path := writeConfig(t, `
listen: ":9090"
monitor: true
max_models: 2
models:
  "org/model-A":
    context: 8192
    gpu_layers: 35
    slots: 4
    pooling: "mean"
  "org/model-B":
    context: 2048
warmup:
  - "org/model-A"
